          '心肌梗塞的病例之間，差別主要在阻塞的機制與心臟受影響範圍的大小，這會影響治療方式與預後。',
          '另外還有暫時性腦缺血發作，症狀會自行消失。它是重要的警訊，需要儘快接受評估，因為之後數日到數個月的腦卒中風險會升高。',
          '缺血性腦卒中的阻塞可能源自大動脈粥樣硬化、心源性栓塞、其他原因，或經詳細檢查後仍找不到原因。辨識這些類型有助於安排檢查與治療。',
