            '認得這組症狀，有助於把偏頭痛與其他類型的頭痛區分開來，也能解釋為什麼即使疼痛看起來不算最劇烈，人卻仍然虛弱無力。如果這些症狀偏離平常的型態，尤其是在從未出現類似發作的人身上，值得盡快就醫評估。',
