            '這種疾病多半是高血壓、心肌梗塞或糖尿病長期損耗心臟之後的最終階段。心臟衰竭不代表心臟停止跳動，而是它的輸送能力低於身體所需，必須持續治療。',
            '巴西衛生部的治療協議估計，全球約有 2,300 萬人罹患此病。在巴西，衛生部指出約有 200 萬人與心臟衰竭共存，每年新增 24 萬個病例。此病也是巴西心血管疾病住院的主要原因之一。',
