            '多數 MASLD 個案背後是體重過重與胰島素阻抗。過重與肥胖約占非酒精性脂肪肝成因的 60%。糖尿病、飲食失衡、高膽固醇、高血壓、久坐、某些藥物、懷孕，以及體重快速增減，也都列在成因之中。',
