            '「腸蠕蟲病」一詞專指由蠕蟲造成的類型，也是巴西與全球最常見的一群。世界衛生組織估計，經土壤傳播的蠕蟲感染了 15 億人，占全球人口的 24%，幾乎全數集中在衛生條件不全的地區。在巴西，感染負荷以北區與東北區最重，兒童是最受影響的群體。',
