            '兩類各自造成不同疾病：蛔蟲病、蟯蟲病、鉤蟲病、鞭蟲病、絛蟲病、賈第蟲病與阿米巴病。認識名稱有助於理解治療，因為藥物與照護方式會隨病原而不同。',
