            '表現會隨寄生蟲而異。賈第蟲常造成油膩腹瀉與腹脹；鉤蟲造成貧血與疲勞；蟯蟲以夜間搔癢為主；蛔蟲多半只是模糊不適，數量多時則可能阻塞腸道。',
