          '病程通常先像一般感冒，有鼻水與輕微咳嗽，幾天才出現呼吸困難：呼吸變快、胸口有喘鳴、看得見用力的動作。多數嬰兒症狀屬輕症，孩子仍然清醒、吃奶也好。但在非常小的嬰兒，這個病可能需要氧氣與住院。',
          '細支氣管炎是全世界幼兒最常見的下呼吸道感染，巴西衛生部描述它是幼童發生急性重度呼吸道症候群（SRAG）的主要原因之一。在巴西，病毒的流行集中在冬季：南半球多數病例出現在 5 月到 7 月之間。',
