          '日常任務時異常疲倦',
          '發作期間排尿次數增加',
          '發作性：心率不快時幾乎沒有感覺；心率上升時出現心悸、呼吸困難、煩躁與疲倦，醫師聽診會發現心音完全沒有節奏、強度每次不同，手腕數到的脈搏少於心臟實際跳動的次數；速度快到極端時心臟無法有效打血，血壓驟降，可能突然昏倒',
