          '腦卒中的徵兆可以在幾秒內辨識：口角歪斜、身體一側無力或麻木、說話或理解困難、視力改變、突然而劇烈的頭痛、意識混亂與平衡喪失。任何一項都必須立即就醫，因為越早獲得救治，存活與完全復原的機會越高。',
