          '飲酒需要特別注意：長期且過量的酒精攝取是心房顫動的公認原因之一，減少攝取對已有心律不整的人有幫助。處理嚴重的打鼾與睡眠呼吸中止也有意義，因為在結合睡眠檢查與心電圖軌跡的分析中，重度睡眠呼吸中止者出現心律不整的比例明顯較高。',
          '每年健檢時一併檢視心臟與甲狀腺，因為這兩個問題都會助長心律不整，且都有治療方法。不需處方就能購買的藥品也值得一併確認：鼻塞藥與止咳糖漿可能含有讓心跳加速的成分。其餘的日常做法包括飲食清淡、營養均衡並增加粗糧與蔬菜等膳食纖維，保持情緒穩定、可藉由聽音樂或深呼吸放鬆，以及規律作息不熬夜，依身體狀況選擇散步、太極等適度運動。',
