          '迅速脹大的肚子、伴隨發燒的腹痛、呼吸困難、非常黃的皮膚，以及無外傷而出現的紫斑，也需要當天就醫，而不是等待預約好的門診。對已有確診肝硬化的人來說，這些發現中的任何一項都代表失代償，而失代償會改變治療計畫。',
