          '甲狀腺是位於頸部前方、形狀像蝴蝶的一隻小腺體，負責製造調控身體能量消耗與體溫的荷爾蒙。當它製造的甲狀腺荷爾蒙少於身體所需，就是甲狀腺功能低下。腺體製造的主要荷爾蒙是甲狀腺素（又稱 T4），並伴隨三碘甲狀腺原氨酸（T3）。',
          '荷爾蒙不足時，身體運作變慢，進入低代謝狀態。因此症狀會同時影響多個系統：能量與體溫、腸道、皮膚與毛髮、情緒、記憶，以及心跳。它是最常見的內分泌疾病之一；因為關係到新陳代謝，通常會與糖尿病、膽固醇過高一併檢視。',
