          '最常見的致病因子是細菌。病毒、支原體與其他微生物也可能感染泌尿道，但一般說泌尿道感染時，指的多半是細菌性感染。泌尿道器官的壁層發炎後會紅腫疼痛，若未處理，感染可能上行到腎臟，嚴重程度與療程長度就跟著改變。',
          '依據 MSD 診療手冊，女性一生中至少發生一次泌尿道感染的比例為 40% 到 50%，男性則只有 5% 到 12%。感冒與流行性感冒之後，泌尿道感染是最常見的感染之一，而由泌尿道感染引發的休克也是造成死亡的感染原因中很重要的一項。多數病例在選對抗生素後幾天內就改善。',
