          '急性發作期的居家照護其實很單純，卻相當關鍵：充足休息、全天持續喝溫開水、維持規律排尿。若有發燒，飲食要選容易消化、營養豐富的食物，例如新鮮蔬菜、雜糧粥、清蒸魚肉，同時補充雞蛋、牛奶等優質蛋白質，烹調以少油、少鹽、少糖為原則。',
