          '三種最常被提到的類型，行為差別很大。基底細胞癌與鱗狀細胞癌統稱非黑色素瘤皮膚癌，多半留在原處、生長緩慢、很少擴散，因此早治的治癒機會很高。黑色素瘤的病例少得多，卻最嚴重，因為它很容易造成轉移，也就是擴散到其他器官；膚色較深的人，它較常出現在手掌、腳底這類顏色較淺的區域，而那正是最不容易被注意的地方。',
