          '最早的跡象通常是皮膚上一處與周圍表現不同的病灶：會癢、會灼熱、會脫皮或會出血的斑，以及四週之內都沒有癒合的傷口。病灶出現在臉、頸與耳朵，正是太陽最先照到的地方。初期幾乎不痛也不太癢，因此很容易被當成一般的皮膚問題。',
          '每一種類型的表現方式不同。基底細胞癌形成長不好的小結節或傷口，邊緣微微隆起、帶有珍珠樣光澤，體積慢慢變大。鱗狀細胞癌多半是質地較硬、短期內明顯長大的塊狀物，摸會痛，表面覆著去不掉的皮屑或結痂，中央可能凹陷成潰瘍。黑色素瘤的典型表現是一顆邊緣不規則的深色痣，伴隨發癢與脫皮；也可能是原本已存在的痣開始變大、顏色與形狀改變。',
