          '太陽對健康有益，但過量會造成提早老化、眼睛損傷與皮膚癌，這是巴西衛生部的提醒。對已經得過皮膚癌的人來說，防曬不再是夏天的建議，而是治療的一環：從家到車站的路、在街邊等人的幾分鐘、公園裡的午後，都屬於會收到紫外線的場合。',
          '皮膚癌患者並沒有絕對必須遵守的飲食禁忌，重點是依照身體狀況攝取足夠的營養，尤其在放射治療期間與手術後的恢復期：食物要多樣，含有優質蛋白質、維生素與足夠熱量，例如魚、蛋、新鮮水果與蔬菜，並避開酒精與過於刺激的食物。體重下降或食慾變差時要告訴醫療團隊，因為可能需要營養補充。每天適度活動，例如散步，對復原有幫助，時段最好避開太陽最強的時刻，也避免大量出汗刺激皮膚。',
          '養成定期檢視自己皮膚的習慣，包括衣服遮住的部位，因為早期發現就取決於這個觀察。在光線充足的地方用鏡子檢查頭皮、耳後與衣服遮住的區域，並在不同日期為病灶拍照，方便回診時比對。刺青要額外留意，因為它可能把病灶藏在圖案之下。把切片報告、治療日期與醫囑留存好，每次回診一併帶去。情緒也是日常的一環：擔心惡化、對治療後外觀改變感到自卑或情緒低落都很常見，特別是在臉部有病灶的人身上，向醫療團隊與家人開口，有助於把療程撐完。',
