          '骨刺本身不是一種疾病。當某一節脊椎變得不穩定時，身體會用這種方式分散重量，就像骨折癒合處的骨頭會變厚一樣。真正的問題出現在骨刺使神經通過的椎管或神經出口變窄時，這時會出現疼痛、麻木與腿部無力。',
          '因此，X 光片上看到骨刺，不代表這個人一定會痛。許多人在因其他原因檢查時才發現骨刺，卻從來沒有任何不適。決定怎麼處理的關鍵是症狀、身體檢查，以及必要時能顯示神經受壓的影像。',
