          '疾病是分階段發展的。在腫瘤出現之前，會先有不會引起症狀、只有篩檢才看得到的癌前病變。在這個階段治療，可以阻止它變成癌症。腫瘤形成之後，會先在局部生長，之後才侵犯淋巴結與其他器官。',
