          '初期症狀類似病毒感染：全身不適、輕微發燒、頭痛、噁心、食慾不振與易怒。許多人在咬傷處感到疼痛、發麻或麻木，即使傷口已經癒合。',
          '前驅期平均持續2到10天。由於症狀不具特異性，這個階段的診斷取決於暴露史：曾被疑似動物咬傷、抓傷或舔舐的人，就醫時一定要主動說明。',
