          '需要排除的疾病包括破傷風、格林巴利症候群、肉毒桿菌中毒、病毒性腦炎與其他神經疾病。暴露史與症狀演變有助於區分。',
          '在登革熱、茲卡或黃熱病流行的地區，這些病毒引起的腦炎也在考量之列。相關檢查多在醫院進行，包括影像與實驗室檢驗。',
