          '膽管型：蟲體進入膽管，右側腹部劇痛',
          '胰臟型：阻塞胰管',
          '腸阻塞：蟲團堵住糞便通道',
          '蛔蟲性闌尾炎：蟲體進入闌尾',
          '腸穿孔：少見但嚴重的併發症',
